// 1. Récupération sécurisée du texte de l'IA
const item = $input.first().json;

let resumeText = 
  item?.choices?.[0]?.message?.content || 
  item?.output || 
  item?.text || 
  item?.content || 
  "Pas de texte trouvé.";

// 2. Nettoyage et conversion du Markdown en HTML propre pour Word
let formattedText = resumeText
  // Titres Markdown (####, ###, ##, #)
  .replace(/^#### (.*$)/gim, '<h4 style="color:#2E75B6; font-family:Calibri; margin-top:15px; margin-bottom:5px;">$1</h4>')
  .replace(/^### (.*$)/gim, '<h3 style="color:#2E75B6; font-family:Calibri; margin-top:18px; margin-bottom:5px;">$1</h3>')
  .replace(/^## (.*$)/gim, '<h2 style="color:#1F4E78; font-family:Calibri; margin-top:20px; margin-bottom:8px;">$1</h2>')
  .replace(/^# (.*$)/gim, '<h1 style="color:#0F243E; font-family:Calibri; border-bottom:2px solid #1F4E78; padding-bottom:5px;">$1</h1>')

  // Lignes de séparation (---)
  .replace(/^---$/gim, '<hr style="border:0; border-top:1px solid #ccc; margin:15px 0;">')

  // Mettre en gras (**texte** ou <b>texte</b>)
  .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')

  // Nettoyage de la notation LaTeX simple pour lisibilité dans Word
  .replace(/\\\[/g, '<div style="text-align:center; margin:10px 0; font-style:italic; background:#f2f4f7; padding:8px; border-radius:4px;">')   .replace(/\\\]/g, '</div>')
  .replace(/\\\((.*?)\\\)/g, '<i>$1</i>')
  .replace(/\\quad/g, ' &nbsp;&nbsp; ')
  .replace(/\\xrightarrow\{(.*?)\}/g, ' &rarr; $1 &rarr; ')

  // Sauts de ligne
  .replace(/\n/g, '<br>');

// Convertir les puces Markdown (- ) en éléments propres
formattedText = formattedText.replace(/<br>- (.*?)(?=<br>|$)/g, '<br>&bull; $1');

// 3. Document HTML/Word avec styles d'impression et de tableaux
const docxHtmlContent = `
<html xmlns:o='urn:schemas-microsoft-com:office:office' 
      xmlns:w='urn:schemas-microsoft-com:office:word' 
      xmlns='http://www.w3.org/TR/REC-html40'>
<head>
    <meta charset="utf-8">
    <title>Résumé de cours</title>
    <!--[if gte mso 9]>
    <xml>
      <w:WordDocument>
        <w:View>Print</w:View>
        <w:Zoom>100</w:Zoom>
        <w:DoNotOptimizeForBrowser/>
      </w:WordDocument>
    </xml>
    <![endif]-->
    <style>
        body {
            font-family: 'Calibri', 'Segoe UI', Arial, sans-serif;
            font-size: 11pt;
            line-height: 1.6;
            color: #262626;
            margin: 1in;
        }
        h1 {
            color: #1F4E78;
            font-size: 20pt;
            border-bottom: 2px solid #1F4E78;
            padding-bottom: 6px;
            margin-bottom: 20px;
        }
        .content-box {
            text-align: justify;
        }
        blockquote {
            background-color: #f9f9f9;
            border-left: 4px solid #1F4E78;
            margin: 15px 0;
            padding: 10px 15px;
            font-style: italic;
        }
    </style>
</head>
<body>
    <h1>Résumé de cours - Généré par IA</h1>
    <div class="content-box">
        ${formattedText}
    </div>
</body>
</html>
`;

// 4. Conversion en Base64 pour n8n (avec transmission du texte pour Qdrant)
const base64Data = Buffer.from(docxHtmlContent, 'utf-8').toString('base64');

return [{
  json: { 
    text: resumeText, // Ajouté pour que Qdrant puisse le lire via {{ $json.text }}
    message: "Document nettoyé et généré avec succès",
    fileName: "Resume_de_cours.docx"
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: 'Resume_de_cours.docx'
    }
  }
}];

const binaryKey = Object.keys(items[0].binary || {})[0];
const binaryData = items[0].binary[binaryKey];
const mimeType = binaryData.mimeType;

// Utilisation de la bonne méthode helper pour récupérer le buffer
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Data = Buffer.from(buffer).toString('base64');

return [{
  json: {
    base64: `data:${mimeType};base64,${base64Data}`
  }
}];

// Récupère le texte de l'examen généré par l'AI Agent
const item = $input.first();
const examenText = item && item.json ? (item.json.output || item.json.text || "Examen généré") : "Examen généré";

// Transformation des sauts de ligne en balises HTML <br> pour un affichage propre
const formattedText = String(examenText)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\n/g, '<br>');

// Construction d'un document HTML compatible Word (.doc)
const wordHtml = `
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
<meta charset="utf-8">
<title>Examen Technique</title>
<style>
  body {
    font-family: 'Calibri', Arial, sans-serif;
    font-size: 11pt;
    color: #333333;
    line-height: 1.6;
    margin: 40px;
  }
  h1 {
    color: #2C3E50;
    font-size: 18pt;
    border-bottom: 2px solid #2C3E50;
    padding-bottom: 8px;
    margin-bottom: 20px;
  }
  .footer {
    font-style: italic;
    font-size: 9pt;
    color: #7F8C8D;
    margin-top: 30px;
    border-top: 1px solid #E0E0E0;
    padding-top: 10px;
  }
</style>
</head>
<body>
  <h1>EXAMEN TECHNIQUE - EVALUATION JAVA (ENISO)</h1>

  <div>${formattedText}</div>

  <div class="footer">
    Généré automatiquement via n8n &amp; IA
  </div>
</body>
</html>
`;

// Encodage propre du Buffer
const buffer = Buffer.from(wordHtml, 'utf-8');

return [{
  json: {
    success: true
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/msword',
      fileName: 'Examen_Technique.doc'
    }
  }
}];

// 1. Contenu réduit (Moitié de l'examen : Exercice 1 uniquement)
let resumeText = `
RÉPUBLIQUE TUNISIENNE - ENISO
EXAMEN : Programmation Orientée Objet (Java - Mai 2022)
Enseignante : Takoua Abdellatif

---

EXERCICE 1 (8 points) : Réseau de capteurs
Dans un réseau de capteurs, on considère une série de capteurs ayant des identifiants uniques ID, avec leurs descriptifs.

1. Écrire en Java une classe Capteur représentant un capteur (redéfinir toString() et equals).
2. Soit la classe ReseauCapteurs qui encapsule un ensemble de capteurs dans une structure illimitée. Justifiez le choix de TreeMap comme structure.
3. Écrire la classe ReseauCapteurs en Java avec les méthodes :
   - Constructeur
   - add et remove (ajout/suppression)
   - getDescriptif(id) (retourne le descriptif)
   - getMaxID() et getMinID() (ID le plus grand et le plus petit)
   - Méthode renvoyant le nombre de capteurs.
4. Donner un diagramme de classe décrivant les classes de l'énoncé et leurs relations.
`;

// 2. Nettoyage et formatage HTML pour Word
let formattedText = resumeText
  .replace(/^#### (.*$)/gim, '<h4 style="color:#2E75B6; font-family:Calibri; margin-top:15px; margin-bottom:5px;">$1</h4>')
  .replace(/^### (.*$)/gim, '<h3 style="color:#2E75B6; font-family:Calibri; margin-top:18px; margin-bottom:5px;">$1</h3>')
  .replace(/^## (.*$)/gim, '<h2 style="color:#1F4E78; font-family:Calibri; margin-top:20px; margin-bottom:8px;">$1</h2>')
  .replace(/^# (.*$)/gim, '<h1 style="color:#0F243E; font-family:Calibri; border-bottom:2px solid #1F4E78; padding-bottom:5px;">$1</h1>')
  .replace(/^---$/gim, '<hr style="border:0; border-top:1px solid #ccc; margin:15px 0;">')
  .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
  .replace(/\n/g, '<br>');

formattedText = formattedText.replace(/<br>- (.*?)(?=<br>|$)/g, '<br>&bull; $1');

// 3. Document HTML Word
const docxHtmlContent = `
<html xmlns:o='urn:schemas-microsoft-com:office:office' 
      xmlns:w='urn:schemas-microsoft-com:office:word' 
      xmlns='http://www.w3.org/TR/REC-html40'>
<head>
    <meta charset="utf-8">
    <title>Exposé Exercice 1 Java</title>
    <!--[if gte mso 9]>
    <xml>
      <w:WordDocument>
        <w:View>Print</w:View>
        <w:Zoom>100</w:Zoom>
        <w:DoNotOptimizeForBrowser/>
      </w:WordDocument>
    </xml>
    <![endif]-->
    <style>
        body {
            font-family: 'Calibri', 'Segoe UI', Arial, sans-serif;
            font-size: 11pt;
            line-height: 1.6;
            color: #262626;
            margin: 1in;
        }
        h1 {
            color: #1F4E78;
            font-size: 16pt;
            border-bottom: 2px solid #1F4E78;
            padding-bottom: 6px;
            margin-bottom: 20px;
        }
        .content-box {
            text-align: justify;
        }
    </style>
</head>
<body>
    <h1>Examen POO Java - Exercice 1 (ENISO)</h1>
    <div class="content-box">
        ${formattedText}
    </div>
</body>
</html>
`;

// 4. Conversion en Base64 pour n8n
const base64Data = Buffer.from(docxHtmlContent, 'utf-8').toString('base64');

return [{
  json: { 
    text: resumeText,
    message: "Moitié d'examen convertie avec succès",
    fileName: "Exercice1_Java_ENISO.docx"
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: 'Exercice1_Java_ENISO.docx'
    }
  }
}];

